def check_balance(chain_id, address, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_naive(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            # store uses naive timestamps with trailing Z
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        # match store prefixes
        return f"ethscan_{prefix}_{uuid.uuid4().hex[:26]}"

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    supported_chains = {1, 5, 11155111, 137, 10, 42161, 56}
    if not _is_int(chain_id) or chain_id not in supported_chains:
        return _err("VALIDATION_ERROR", "Unsupported or invalid chain_id.", supported_chain_ids=sorted(supported_chains))
    if not isinstance(address, str) or re.fullmatch(r"0x[0-9a-fA-F]{40}", address or "") is None:
        return _err("VALIDATION_ERROR", "Invalid address format; expected 0x-prefixed 20-byte hex string.", field="address")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided.", field="refresh")
    refresh = bool(refresh) if refresh is not None else False

    addr = address.lower()

    api_keys = _load("api_keys.json")
    reqs = _load("requests.json")
    addr_states = _load("address_state.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(reqs, list):
        reqs = []
    if not isinstance(addr_states, list):
        addr_states = []

    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _count_for_key(key_id, since_dt):
        c = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            dt = _parse_iso_naive(r.get("created_at"))
            if dt and dt >= since_dt:
                c += 1
        return c

    # Ambient auth: choose any key that can serve this request (active + allowed chain).
    chosen_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        allowed = k.get("allowed_chain_ids")
        if not isinstance(allowed, list) or chain_id not in allowed:
            continue
        chosen_key = k
        break

    # Prepare a requests row now (must always record exactly one request row per invocation)
    req_row = {
        "id": _new_id("req"),
        "api_key_id": chosen_key.get("id") if isinstance(chosen_key, dict) else None,
        "tool_name": "check-balance",
        "chain_id": chain_id,
        "subject_address": addr,
        "contract_address": None,
        "cache_hit": False,
        "upstream_provider": "none",
        "upstream_http_status": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "response_ref": None,
        "latency_ms": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }

    def _finalize_and_return(payload):
        # finalize request row and persist
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _now_iso()
        reqs.append(req_row)
        _save("requests.json", reqs)
        # update last_used_at if possible
        if chosen_key and isinstance(chosen_key, dict) and chosen_key.get("id"):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == chosen_key["id"]:
                    k["last_used_at"] = req_row["created_at"]
                    k["updated_at"] = _now_iso()
                    break
            _save("api_keys.json", api_keys)
        return payload

    if chosen_key is None:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No active API key available that is allowed to query this chain."
        return _finalize_and_return(_err("UNAUTHORIZED", "No active API key available for this chain.", chain_id=chain_id))

    # Enforce key status (active only)
    if chosen_key.get("status") != "active":
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "API_KEY_INACTIVE"
        req_row["error_message"] = "API key is not active."
        return _finalize_and_return(_err("RATE_LIMIT", "API key is not active.", api_key_id=chosen_key.get("id")))

    # Enforce per-minute rate limit and daily quota (applies to all calls)
    per_min = chosen_key.get("rate_limit_per_minute")
    daily_q = chosen_key.get("daily_quota")
    if not _is_int(per_min) or not (1 <= per_min <= 6000):
        per_min = 60
    if not _is_int(daily_q) or not (1 <= daily_q <= 10000000):
        daily_q = 100000

    used_min = _count_for_key(chosen_key["id"], one_min_ago)
    used_day = _count_for_key(chosen_key["id"], day_ago)
    if used_min >= per_min:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "PER_MINUTE_RATE_LIMIT_EXCEEDED"
        req_row["error_message"] = "Per-minute request limit exceeded for API key."
        return _finalize_and_return(_err("RATE_LIMIT", "Per-minute request limit exceeded.", limit=per_min, window_seconds=60))
    if used_day >= daily_q:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily request quota exceeded for API key."
        return _finalize_and_return(_err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=daily_q, window_seconds=86400))

    # Read/write address_state by (chain_id, address); create if missing
    addr_state = None
    for s in addr_states:
        if not isinstance(s, dict):
            continue
        if s.get("chain_id") == chain_id and s.get("address") == addr:
            addr_state = s
            break
    if addr_state is None:
        now = _now_iso()
        addr_state = {
            "id": _new_id("addr"),
            "chain_id": chain_id,
            "address": addr,
            "balance_wei": None,
            "balance_as_of_block": None,
            "ens_name": None,
            "ens_checked_at": None,
            "tx_synced_through_block": None,
            "token_transfers_synced_through_block": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        addr_states.append(addr_state)
        _save("address_state.json", addr_states)

    # Serve cached unless refresh requested
    cache_hit = (not refresh) and (addr_state.get("balance_wei") is not None)
    req_row["cache_hit"] = bool(cache_hit)
    if cache_hit:
        req_row["status"] = "served"
        req_row["upstream_provider"] = "none"
        req_row["response_ref"] = {"entity": "address_state", "id": addr_state.get("id"), "as_of": addr_state.get("updated_at")}
        return _finalize_and_return(
            {
                "chain_id": chain_id,
                "address": addr,
                "balance_wei": addr_state.get("balance_wei"),
                "balance_as_of_block": addr_state.get("balance_as_of_block"),
                "as_of": addr_state.get("updated_at"),
                "address_state": addr_state,
            }
        )

    # Offline "refresh": update last_fetched fields best-effort without fabricating upstream data.
    # If we have any cached value, serve it as stale but still mark as served; if none, fail.
    if addr_state.get("balance_wei") is None:
        req_row["status"] = "failed"
        req_row["upstream_provider"] = "etherscan"
        req_row["upstream_http_status"] = None
        req_row["error_code"] = "NO_CACHED_BALANCE"
        req_row["error_message"] = "No cached balance available and upstream refresh is unavailable in this datastore-backed environment."
        return _finalize_and_return(_err("CONFLICT", "No cached balance available to serve and cannot refresh from upstream offline.", upstream="etherscan"))

    # We "refreshed" but only had cached data; keep snapshot, touch updated_at
    addr_state["updated_at"] = _now_iso()
    _save("address_state.json", addr_states)

    req_row["status"] = "served"
    req_row["upstream_provider"] = "etherscan"
    req_row["upstream_http_status"] = 200
    req_row["response_ref"] = {"entity": "address_state", "id": addr_state.get("id"), "as_of": addr_state.get("updated_at")}
    return _finalize_and_return(
        {
            "chain_id": chain_id,
            "address": addr,
            "balance_wei": addr_state.get("balance_wei"),
            "balance_as_of_block": addr_state.get("balance_as_of_block"),
            "as_of": addr_state.get("updated_at"),
            "address_state": addr_state,
            "note": "Served cached balance; upstream refresh not available offline.",
        }
    )

def get_transactions(chain_id, address, start_block=None, end_block=None, sort=None, page=None, page_size=None, refresh=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    supported_chains = {1, 5, 11155111, 137, 10, 42161, 56}
    if not isinstance(chain_id, int) or chain_id not in supported_chains:
        return _err("VALIDATION_ERROR", "Unsupported or invalid chain_id.", supported_chain_ids=sorted(supported_chains))
    if not isinstance(address, str) or not re.fullmatch(r"0x[0-9a-fA-F]{40}", address or ""):
        return _err("VALIDATION_ERROR", "Invalid address format; expected 0x-prefixed 20-byte hex string.")
    if start_block is not None and (not isinstance(start_block, int) or start_block < 0):
        return _err("VALIDATION_ERROR", "start_block must be an integer >= 0 when provided.")
    if end_block is not None and (not isinstance(end_block, int) or end_block < 0):
        return _err("VALIDATION_ERROR", "end_block must be an integer >= 0 when provided.")
    if start_block is not None and end_block is not None and start_block > end_block:
        return _err("VALIDATION_ERROR", "start_block cannot be greater than end_block.")
    if sort is not None and sort not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort must be 'asc' or 'desc' when provided.")
    if page is not None and (not isinstance(page, int) or page <= 0):
        return _err("VALIDATION_ERROR", "page must be a positive integer (1-based) when provided.")
    if page_size is not None and (not isinstance(page_size, int) or page_size <= 0 or page_size > 10000):
        return _err("VALIDATION_ERROR", "page_size must be a positive integer <= 10000 when provided.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided.")
    refresh = bool(refresh) if refresh is not None else False
    sort = sort or "desc"
    page = page or 1
    page_size = page_size or 100

    addr = address.lower()

    api_keys = _load("api_keys.json")
    requests = _load("requests.json")
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(requests, list): requests = []

    def _parse_dt(s):
        if not s: return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _count_for_key(key_id, since_dt):
        c = 0
        for r in requests:
            if r.get("api_key_id") != key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= since_dt:
                c += 1
        return c

    chosen = None
    rate_limited_reason = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        allowed = k.get("allowed_chain_ids")
        if not isinstance(allowed, list) or chain_id not in allowed:
            continue
        rl = k.get("rate_limit_per_minute")
        dq = k.get("daily_quota")
        if not isinstance(rl, int) or not (1 <= rl <= 6000): 
            continue
        if not isinstance(dq, int) or not (1 <= dq <= 10000000):
            continue
        if _count_for_key(k.get("id"), one_min_ago) >= rl:
            rate_limited_reason = ("RATE_LIMIT", "Per-minute rate limit exceeded for available credentials.")
            continue
        if _count_for_key(k.get("id"), day_ago) >= dq:
            rate_limited_reason = ("QUOTA_EXCEEDED", "Daily quota exceeded for available credentials.")
            continue
        chosen = k
        break

    def _new_id(prefix):
        return prefix + "_" + secrets.token_hex(12)

    def _record_request(api_key_id, final_status, error_code=None, error_message=None, cache_hit=False,
                        upstream_provider=None, upstream_http_status=None, response_ref=None, latency_ms=None):
        req = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "get-transactions",
            "chain_id": chain_id,
            "subject_address": address,
            "contract_address": None,
            "cache_hit": bool(cache_hit),
            "upstream_provider": upstream_provider if upstream_provider in ("etherscan", "none", None) else None,
            "upstream_http_status": upstream_http_status if isinstance(upstream_http_status, int) else None,
            "status": "received",
            "error_code": error_code,
            "error_message": error_message,
            "response_ref": response_ref if isinstance(response_ref, (dict, type(None))) else None,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) and latency_ms >= 0 else None,
            "created_at": now,
            "updated_at": now,
        }
        if final_status not in ("served", "failed", "rate_limited"):
            final_status = "failed"
        req["status"] = final_status
        req["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        requests.append(req)
        _save("requests.json", requests)
        return req

    if chosen is None:
        if rate_limited_reason:
            code, msg = rate_limited_reason
            key_id = None
            for k in api_keys:
                if isinstance(k, dict) and chain_id in (k.get("allowed_chain_ids") or []):
                    key_id = k.get("id"); break
            if not key_id and api_keys:
                key_id = api_keys[0].get("id")
            if not key_id:
                return _err(code, msg)
            _record_request(key_id, "rate_limited", error_code=code, error_message=msg,
                            cache_hit=False, upstream_provider="none",
                            latency_ms=(time.time() - t0) * 1000)
            return _err(code, msg)
        return _err("UNAUTHORIZED", "No active API key available for this operation.")

    api_key_id = chosen.get("id")

    address_state = _load("address_state.json")
    if not isinstance(address_state, list): address_state = []
    st = None
    for row in address_state:
        if isinstance(row, dict) and row.get("chain_id") == chain_id and row.get("address") == addr:
            st = row
            break
    if st is None:
        st = {
            "id": _new_id("addr"),
            "chain_id": chain_id,
            "address": addr,
            "balance_wei": None,
            "balance_as_of_block": None,
            "ens_name": None,
            "ens_checked_at": None,
            "tx_synced_through_block": None,
            "token_transfers_synced_through_block": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        address_state.append(st)
        _save("address_state.json", address_state)

    cache_hit = not refresh
    upstream_provider = "none"
    upstream_http_status = None

    if refresh:
        cache_hit = False
        upstream_provider = "etherscan"
        upstream_http_status = 503
        st["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("address_state.json", address_state)

    transactions = _load("transactions.json")
    if not isinstance(transactions, list): transactions = []

    rows = [tx for tx in transactions if isinstance(tx, dict) and tx.get("chain_id") == chain_id and tx.get("address_state_id") == st.get("id")]
    if start_block is not None:
        rows = [tx for tx in rows if isinstance(tx.get("block_number"), int) and tx.get("block_number") >= start_block]
    if end_block is not None:
        rows = [tx for tx in rows if isinstance(tx.get("block_number"), int) and tx.get("block_number") <= end_block]

    # sort: primary by block_number, secondary tx_index (None last in desc, first in asc)
    def _tx_index_key(v):
        if v is None:
            return (1, 0)  # mark missing
        if isinstance(v, int):
            return (0, v)
        return (1, 0)

    reverse = (sort == "desc")
    rows.sort(key=lambda r: (r.get("block_number", -1), _tx_index_key(r.get("tx_index"))), reverse=reverse)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    chosen["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    chosen["updated_at"] = chosen["last_used_at"]
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    response_ref = {"entity": "address_state", "id": st.get("id"), "as_of": st.get("updated_at")}

    if refresh and upstream_http_status != 200:
        _record_request(api_key_id, "failed", error_code="UPSTREAM_UNAVAILABLE",
                        error_message="Upstream refresh requested but upstream is unavailable in offline mode.",
                        cache_hit=cache_hit, upstream_provider=upstream_provider,
                        upstream_http_status=upstream_http_status, response_ref=response_ref, latency_ms=latency_ms)
        return _err("CONFLICT", "Unable to refresh from upstream in offline mode.", upstream="etherscan")

    _record_request(api_key_id, "served", cache_hit=cache_hit, upstream_provider=upstream_provider,
                    upstream_http_status=upstream_http_status, response_ref=response_ref, latency_ms=latency_ms)

    return {
        "chain_id": chain_id,
        "address": addr,
        "sort": sort,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "results": page_rows,
    }

def get_token_transfers(chain_id, address, contract_address=None, start_block=None, end_block=None, sort=None, page=None, page_size=None, refresh=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    supported_chains = {1, 5, 11155111, 137, 10, 42161, 56}
    if not isinstance(chain_id, int) or chain_id not in supported_chains:
        return _err("VALIDATION_ERROR", "Unsupported or invalid chain_id.", supported_chain_ids=sorted(supported_chains))
    if not isinstance(address, str) or not re.fullmatch(r"0x[0-9a-fA-F]{40}", address or ""):
        return _err("VALIDATION_ERROR", "Invalid address format; expected 0x-prefixed 20-byte hex string.")
    if contract_address is not None:
        if not isinstance(contract_address, str) or not re.fullmatch(r"0x[0-9a-fA-F]{40}", contract_address or ""):
            return _err("VALIDATION_ERROR", "Invalid contract_address format; expected 0x-prefixed 20-byte hex string.")
    if start_block is not None and (not isinstance(start_block, int) or start_block < 0):
        return _err("VALIDATION_ERROR", "start_block must be an integer >= 0 when provided.")
    if end_block is not None and (not isinstance(end_block, int) or end_block < 0):
        return _err("VALIDATION_ERROR", "end_block must be an integer >= 0 when provided.")
    if start_block is not None and end_block is not None and start_block > end_block:
        return _err("VALIDATION_ERROR", "start_block cannot be greater than end_block.")
    if sort is not None and sort not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort must be 'asc' or 'desc' when provided.")
    if page is not None and (not isinstance(page, int) or page <= 0):
        return _err("VALIDATION_ERROR", "page must be a positive integer (1-based) when provided.")
    if page_size is not None and (not isinstance(page_size, int) or page_size <= 0 or page_size > 10000):
        return _err("VALIDATION_ERROR", "page_size must be a positive integer <= 10000 when provided.")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided.")
    refresh = bool(refresh) if refresh is not None else False
    sort = sort or "desc"
    page = page or 1
    page_size = page_size or 100

    addr = address.lower()
    caddr = contract_address.lower() if isinstance(contract_address, str) else None

    api_keys = _load("api_keys.json")
    requests = _load("requests.json")
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(requests, list): requests = []

    def _parse_dt(s):
        if not s: return None
        try:
            if s.endswith("Z"): s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _count_for_key(key_id, since_dt):
        c = 0
        for r in requests:
            if r.get("api_key_id") != key_id:
                continue
            dt = _parse_dt(r.get("created_at"))
            if dt and dt >= since_dt:
                c += 1
        return c

    chosen = None
    rate_limited_reason = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        allowed = k.get("allowed_chain_ids")
        if not isinstance(allowed, list) or chain_id not in allowed:
            continue
        rl = k.get("rate_limit_per_minute")
        dq = k.get("daily_quota")
        if not isinstance(rl, int) or not (1 <= rl <= 6000):
            continue
        if not isinstance(dq, int) or not (1 <= dq <= 10000000):
            continue
        if _count_for_key(k.get("id"), one_min_ago) >= rl:
            rate_limited_reason = ("RATE_LIMIT", "Per-minute rate limit exceeded for available credentials.")
            continue
        if _count_for_key(k.get("id"), day_ago) >= dq:
            rate_limited_reason = ("QUOTA_EXCEEDED", "Daily quota exceeded for available credentials.")
            continue
        chosen = k
        break

    def _new_id(prefix):
        return prefix + "_" + secrets.token_hex(12)

    def _record_request(api_key_id, final_status, error_code=None, error_message=None, cache_hit=False,
                        upstream_provider=None, upstream_http_status=None, response_ref=None, latency_ms=None):
        req = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "get-token-transfers",
            "chain_id": chain_id,
            "subject_address": address,
            "contract_address": contract_address if contract_address is not None else None,
            "cache_hit": bool(cache_hit),
            "upstream_provider": upstream_provider if upstream_provider in ("etherscan", "none", None) else None,
            "upstream_http_status": upstream_http_status if isinstance(upstream_http_status, int) else None,
            "status": "received",
            "error_code": error_code,
            "error_message": error_message,
            "response_ref": response_ref if isinstance(response_ref, (dict, type(None))) else None,
            "latency_ms": int(latency_ms) if isinstance(latency_ms, (int, float)) and latency_ms >= 0 else None,
            "created_at": now,
            "updated_at": now,
        }
        if final_status not in ("served", "failed", "rate_limited"):
            final_status = "failed"
        req["status"] = final_status
        req["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        requests.append(req)
        _save("requests.json", requests)
        return req

    if chosen is None:
        if rate_limited_reason:
            code, msg = rate_limited_reason
            key_id = None
            for k in api_keys:
                if isinstance(k, dict) and chain_id in (k.get("allowed_chain_ids") or []):
                    key_id = k.get("id"); break
            if not key_id and api_keys:
                key_id = api_keys[0].get("id")
            if not key_id:
                return _err(code, msg)
            _record_request(key_id, "rate_limited", error_code=code, error_message=msg,
                            cache_hit=False, upstream_provider="none",
                            latency_ms=(time.time() - t0) * 1000)
            return _err(code, msg)
        return _err("UNAUTHORIZED", "No active API key available for this operation.")

    api_key_id = chosen.get("id")

    address_state = _load("address_state.json")
    if not isinstance(address_state, list): address_state = []
    st = None
    for row in address_state:
        if isinstance(row, dict) and row.get("chain_id") == chain_id and row.get("address") == addr:
            st = row
            break
    if st is None:
        st = {
            "id": _new_id("addr"),
            "chain_id": chain_id,
            "address": addr,
            "balance_wei": None,
            "balance_as_of_block": None,
            "ens_name": None,
            "ens_checked_at": None,
            "tx_synced_through_block": None,
            "token_transfers_synced_through_block": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        address_state.append(st)
        _save("address_state.json", address_state)

    cache_hit = not refresh
    upstream_provider = "none"
    upstream_http_status = None

    if refresh:
        cache_hit = False
        upstream_provider = "etherscan"
        upstream_http_status = 503
        st["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("address_state.json", address_state)

    transfers = _load("token_transfers.json")
    if not isinstance(transfers, list): transfers = []

    rows = [tr for tr in transfers if isinstance(tr, dict) and tr.get("chain_id") == chain_id and tr.get("address_state_id") == st.get("id")]
    if caddr is not None:
        rows = [tr for tr in rows if tr.get("token_contract") == caddr]
    if start_block is not None:
        rows = [tr for tr in rows if isinstance(tr.get("block_number"), int) and tr.get("block_number") >= start_block]
    if end_block is not None:
        rows = [tr for tr in rows if isinstance(tr.get("block_number"), int) and tr.get("block_number") <= end_block]

    reverse = (sort == "desc")
    rows.sort(key=lambda r: (r.get("block_number", -1), r.get("log_index", -1)), reverse=reverse)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    chosen["last_used_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    chosen["updated_at"] = chosen["last_used_at"]
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    response_ref = {"entity": "address_state", "id": st.get("id"), "as_of": st.get("updated_at")}

    if refresh and upstream_http_status != 200:
        _record_request(api_key_id, "failed", error_code="UPSTREAM_UNAVAILABLE",
                        error_message="Upstream refresh requested but upstream is unavailable in offline mode.",
                        cache_hit=cache_hit, upstream_provider=upstream_provider,
                        upstream_http_status=upstream_http_status, response_ref=response_ref, latency_ms=latency_ms)
        return _err("CONFLICT", "Unable to refresh from upstream in offline mode.", upstream="etherscan")

    _record_request(api_key_id, "served", cache_hit=cache_hit, upstream_provider=upstream_provider,
                    upstream_http_status=upstream_http_status, response_ref=response_ref, latency_ms=latency_ms)

    return {
        "chain_id": chain_id,
        "address": addr,
        "contract_address": caddr,
        "sort": sort,
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "results": page_rows,
    }

def get_contract_abi(chain_id, contract_address, refresh=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_naive(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1]
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _new_id(prefix):
        return f"ethscan_{prefix}_{uuid.uuid4().hex[:26]}"

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    supported_chains = {1, 5, 11155111, 137, 10, 42161, 56}
    if not _is_int(chain_id) or chain_id not in supported_chains:
        return _err("VALIDATION_ERROR", "Unsupported or invalid chain_id.", supported_chain_ids=sorted(supported_chains))
    if not isinstance(contract_address, str) or re.fullmatch(r"0x[0-9a-fA-F]{40}", contract_address or "") is None:
        return _err("VALIDATION_ERROR", "Invalid contract_address format; expected 0x-prefixed 20-byte hex string.", field="contract_address")
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided.", field="refresh")
    refresh = bool(refresh) if refresh is not None else False

    caddr = contract_address.lower()

    api_keys = _load("api_keys.json")
    reqs = _load("requests.json")
    ctrs = _load("contract_metadata.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(reqs, list):
        reqs = []
    if not isinstance(ctrs, list):
        ctrs = []

    now_dt = datetime.datetime.utcnow()
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _count_for_key(key_id, since_dt):
        c = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != key_id:
                continue
            dt = _parse_iso_naive(r.get("created_at"))
            if dt and dt >= since_dt:
                c += 1
        return c

    # choose an active key allowed for this chain
    chosen_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        allowed = k.get("allowed_chain_ids")
        if not isinstance(allowed, list) or chain_id not in allowed:
            continue
        chosen_key = k
        break

    req_row = {
        "id": _new_id("req"),
        "api_key_id": chosen_key.get("id") if isinstance(chosen_key, dict) else None,
        "tool_name": "get-contract-abi",
        "chain_id": chain_id,
        "subject_address": None,
        "contract_address": caddr,
        "cache_hit": False,
        "upstream_provider": "none",
        "upstream_http_status": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "response_ref": None,
        "latency_ms": None,
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }

    def _finalize(payload):
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _now_iso()
        reqs.append(req_row)
        _save("requests.json", reqs)
        if chosen_key and isinstance(chosen_key, dict) and chosen_key.get("id"):
            for k in api_keys:
                if isinstance(k, dict) and k.get("id") == chosen_key["id"]:
                    k["last_used_at"] = req_row["created_at"]
                    k["updated_at"] = _now_iso()
                    break
            _save("api_keys.json", api_keys)
        return payload

    if chosen_key is None:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "UNAUTHORIZED"
        req_row["error_message"] = "No active API key available that is allowed to query this chain."
        return _finalize(_err("UNAUTHORIZED", "No active API key available for this chain.", chain_id=chain_id))

    per_min = chosen_key.get("rate_limit_per_minute")
    daily_q = chosen_key.get("daily_quota")
    if not _is_int(per_min) or not (1 <= per_min <= 6000):
        per_min = 60
    if not _is_int(daily_q) or not (1 <= daily_q <= 10000000):
        daily_q = 100000
    if _count_for_key(chosen_key["id"], one_min_ago) >= per_min:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "PER_MINUTE_RATE_LIMIT_EXCEEDED"
        req_row["error_message"] = "Per-minute request limit exceeded for API key."
        return _finalize(_err("RATE_LIMIT", "Per-minute request limit exceeded.", limit=per_min, window_seconds=60))
    if _count_for_key(chosen_key["id"], day_ago) >= daily_q:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "DAILY_QUOTA_EXCEEDED"
        req_row["error_message"] = "Daily request quota exceeded for API key."
        return _finalize(_err("QUOTA_EXCEEDED", "Daily request quota exceeded.", limit=daily_q, window_seconds=86400))

    # Fetch contract_metadata row by (chain_id, contract_address)
    meta = None
    for r in ctrs:
        if not isinstance(r, dict):
            continue
        if r.get("chain_id") == chain_id and r.get("contract_address") == caddr:
            meta = r
            break

    if meta is None:
        # Real system would create on refresh. But we cannot fabricate ABI; still create placeholder on refresh to satisfy read/write rule.
        if refresh:
            now = _now_iso()
            meta = {
                "id": _new_id("ctr"),
                "chain_id": chain_id,
                "contract_address": caddr,
                "contract_name": None,
                "abi_json": None,
                "source_code": None,
                "compiler_version": None,
                "optimization_enabled": None,
                "runs": None,
                "license_type": None,
                "verified": False,
                "last_fetched_at": now,
                "status": "missing",
                "created_at": now,
                "updated_at": now,
            }
            ctrs.append(meta)
            _save("contract_metadata.json", ctrs)

            req_row["cache_hit"] = False
            req_row["upstream_provider"] = "etherscan"
            req_row["upstream_http_status"] = None
            req_row["status"] = "failed"
            req_row["error_code"] = "CONTRACT_NOT_VERIFIED"
            req_row["error_message"] = "Contract source/ABI not verified on explorer for this network"
            req_row["response_ref"] = {"entity": "contract_metadata", "id": meta.get("id"), "as_of": meta.get("last_fetched_at")}
            return _finalize(_err("NOT_FOUND", "Contract ABI not available (missing/unverified).", error_code="CONTRACT_NOT_VERIFIED"))

        # no row and no refresh: empty cache => not found
        req_row["cache_hit"] = False
        req_row["status"] = "failed"
        req_row["error_code"] = "NOT_CACHED"
        req_row["error_message"] = "No cached contract metadata available."
        return _finalize(_err("NOT_FOUND", "No cached contract metadata for this contract."))

    # Determine if we can serve from cache
    ttl_seconds = 6 * 3600
    last_fetched = _parse_iso_naive(meta.get("last_fetched_at"))
    expired = True if last_fetched is None else ((now_dt - last_fetched).total_seconds() > ttl_seconds)
    needs_refresh = refresh or meta.get("status") in ("stale", "missing") or expired

    if not needs_refresh:
        req_row["cache_hit"] = True
        req_row["status"] = "served"
        req_row["upstream_provider"] = "none"
        req_row["response_ref"] = {"entity": "contract_metadata", "id": meta.get("id"), "as_of": meta.get("last_fetched_at")}
        return _finalize(
            {
                "chain_id": chain_id,
                "contract_address": caddr,
                "verified": bool(meta.get("verified")),
                "abi_json": meta.get("abi_json"),
                "contract_metadata": meta,
                "as_of": meta.get("last_fetched_at"),
            }
        )

    # Offline refresh behavior: do not error if cache exists; update last_fetched_at/status conservatively
    now = _now_iso()
    meta["last_fetched_at"] = now
    meta["updated_at"] = now
    # If it was stale, mark as stale still (we didn't actually fetch); if missing, keep missing.
    if meta.get("status") == "fresh":
        meta["status"] = "stale"
    _save("contract_metadata.json", ctrs)

    # Serve what we have; if none, return not found with stable error code
    req_row["cache_hit"] = False
    req_row["upstream_provider"] = "etherscan"
    req_row["upstream_http_status"] = 200 if meta.get("abi_json") is not None else None
    req_row["response_ref"] = {"entity": "contract_metadata", "id": meta.get("id"), "as_of": meta.get("last_fetched_at")}

    if meta.get("abi_json") is None:
        req_row["status"] = "failed"
        req_row["error_code"] = "CONTRACT_NOT_VERIFIED"
        req_row["error_message"] = "Contract source/ABI not verified on explorer for this network"
        return _finalize(_err("NOT_FOUND", "Contract ABI not available (missing/unverified).", error_code="CONTRACT_NOT_VERIFIED"))

    req_row["status"] = "served"
    return _finalize(
        {
            "chain_id": chain_id,
            "contract_address": caddr,
            "verified": bool(meta.get("verified")),
            "abi_json": meta.get("abi_json"),
            "contract_metadata": meta,
            "as_of": meta.get("last_fetched_at"),
            "note": "Served cached ABI; upstream refresh not available offline.",
        }
    )

def get_contract_code(chain_id, contract_address, refresh=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate inputs
    if not isinstance(chain_id, int):
        return _err("VALIDATION_ERROR", "chain_id must be an integer")
    supported_chains = {1, 5, 11155111, 137, 10, 42161, 56}
    if chain_id not in supported_chains:
        return _err("VALIDATION_ERROR", "Unsupported chain_id", supported_chain_ids=sorted(list(supported_chains)))
    if not isinstance(contract_address, str):
        return _err("VALIDATION_ERROR", "contract_address must be a string")
    if not re.fullmatch(r"^0x[0-9a-fA-F]{40}$", contract_address or ""):
        return _err("VALIDATION_ERROR", "contract_address must be a 0x-prefixed 20-byte hex string")
    contract_address_n = contract_address.lower()
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided")

    api_keys = _load("api_keys.json")
    requests = _load("requests.json")
    contract_metadata = _load("contract_metadata.json")

    # Resolve an authorized API key context (ambient auth): any active key that can query this chain
    def _pick_key():
        for k in api_keys:
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_chain_ids")
            if isinstance(allowed, list) and chain_id in allowed:
                return k
        return None

    key = _pick_key()
    if not key:
        # Must still record a request row? Business rules say every tool invocation must create exactly one requests row,
        # but we cannot reference a non-existent api_key_id (non-null FK). Return UNAUTHORIZED.
        return _err("UNAUTHORIZED", "No active API key is permitted to access this chain_id")

    # Rate limit / quota check (enforced against requests log)
    key_id = key["id"]
    minute_window_start = (datetime.datetime.utcnow().replace(second=0, microsecond=0) - datetime.timedelta(minutes=0))
    # For per-minute rate limiting use last 60 seconds window
    window_start = (datetime.datetime.utcnow() - datetime.timedelta(seconds=60)).replace(microsecond=0).isoformat() + "Z"
    day_start = datetime.datetime.utcnow().date().isoformat()  # YYYY-MM-DD
    per_minute = int(key.get("rate_limit_per_minute", 0) or 0)
    daily_quota = int(key.get("daily_quota", 0) or 0)

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    window_start_dt = now_dt - datetime.timedelta(seconds=60)
    day_start_dt = datetime.datetime.fromisoformat(day_start)

    reqs_for_key = [r for r in requests if r.get("api_key_id") == key_id]
    used_last_minute = 0
    used_today = 0
    for r in reqs_for_key:
        ts = _parse_ts(r.get("created_at"))
        if not ts:
            continue
        if ts >= window_start_dt:
            used_last_minute += 1
        if ts >= day_start_dt:
            used_today += 1

    should_rate_limit = False
    rate_reason = None
    if key.get("status") != "active":
        should_rate_limit = True
        rate_reason = "API key is not active"
    elif per_minute and used_last_minute >= per_minute:
        should_rate_limit = True
        rate_reason = "Per-minute rate limit exceeded"
    elif daily_quota and used_today >= daily_quota:
        should_rate_limit = True
        rate_reason = "Daily quota exceeded"

    # Create request row (received), then transition
    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + now + str(time.time())).encode('utf-8')).hexdigest()[:24]}"

    req_id = _new_id("req")
    req_row = {
        "id": req_id,
        "api_key_id": key_id,
        "tool_name": "get-contract-code",
        "chain_id": chain_id,
        "subject_address": None,
        "contract_address": contract_address_n,
        "cache_hit": False,
        "upstream_provider": None,
        "upstream_http_status": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "response_ref": None,
        "latency_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    requests.append(req_row)
    _save("requests.json", requests)

    if should_rate_limit:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "RATE_LIMIT"
        req_row["error_message"] = rate_reason
        req_row["upstream_provider"] = "none"
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("requests.json", requests)
        return _err("RATE_LIMIT", rate_reason, request_id=req_id)

    # Update api_keys.last_used_at
    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    # Cache/TTL logic
    TTL_SECONDS = 6 * 60 * 60  # 6h
    def _find_meta():
        for m in contract_metadata:
            if m.get("chain_id") == chain_id and m.get("contract_address") == contract_address_n:
                return m
        return None

    meta = _find_meta()
    cache_hit = False
    needs_refresh = bool(refresh) if refresh is not None else False
    if meta:
        last_fetched = _parse_ts(meta.get("last_fetched_at"))
        age_ok = False
        if last_fetched:
            age_ok = (now_dt - last_fetched).total_seconds() <= TTL_SECONDS
        if meta.get("status") in ("stale", "missing") or not age_ok:
            needs_refresh = True if refresh is None else bool(refresh)
        else:
            # fresh or blocked treated as serve from cache unless explicit refresh
            pass
    else:
        # create missing cache row if we will store; also, if no row and refresh not explicitly false, we can "refresh"
        needs_refresh = True if (refresh is None or refresh is True) else False

    # Offline "upstream refresh": we cannot call Etherscan, so we can only update freshness timestamps for existing data.
    upstream_provider = "none"
    upstream_http_status = None
    if needs_refresh:
        upstream_provider = "etherscan"
        upstream_http_status = 503  # unavailable offline
        if meta:
            # Mark stale if attempted refresh failed and wasn't blocked
            if meta.get("status") != "blocked":
                meta["status"] = "stale"
            meta["last_fetched_at"] = now
            meta["updated_at"] = now
        else:
            meta = {
                "id": _new_id("cmeta"),
                "chain_id": chain_id,
                "contract_address": contract_address_n,
                "contract_name": None,
                "abi_json": None,
                "source_code": None,
                "compiler_version": None,
                "optimization_enabled": None,
                "runs": None,
                "license_type": None,
                "verified": False,
                "last_fetched_at": now,
                "status": "missing",
                "created_at": now,
                "updated_at": now,
            }
            contract_metadata.append(meta)
        _save("contract_metadata.json", contract_metadata)
        cache_hit = False
    else:
        cache_hit = True

    # Prepare response from cache row (may be missing/null)
    body = {
        "contract": {
            "chain_id": chain_id,
            "contract_address": contract_address_n,
            "verified": bool(meta.get("verified")) if meta else False,
            "status": meta.get("status") if meta else "missing",
            "last_fetched_at": meta.get("last_fetched_at") if meta else None,
            "contract_name": meta.get("contract_name") if meta else None,
            "compiler_version": meta.get("compiler_version") if meta else None,
            "optimization_enabled": meta.get("optimization_enabled") if meta else None,
            "runs": meta.get("runs") if meta else None,
            "license_type": meta.get("license_type") if meta else None,
            "source_code": meta.get("source_code") if meta else None,
        },
        "cache": {"hit": bool(cache_hit)},
        "request_id": req_id,
    }

    # Transition request -> served (even if unverified/missing; it's a valid served response)
    req_row["status"] = "served"
    req_row["cache_hit"] = bool(cache_hit)
    req_row["upstream_provider"] = upstream_provider
    req_row["upstream_http_status"] = upstream_http_status
    req_row["response_ref"] = {"entity": "contract_metadata", "id": meta.get("id") if meta else None, "as_of": meta.get("last_fetched_at") if meta else now}
    req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
    req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("requests.json", requests)
    return body

def get_gas_prices(chain_id, refresh=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    if not isinstance(chain_id, int):
        return _err("VALIDATION_ERROR", "chain_id must be an integer")
    supported_chains = {1, 5, 11155111, 137, 10, 42161, 56}
    if chain_id not in supported_chains:
        return _err("VALIDATION_ERROR", "Unsupported chain_id", supported_chain_ids=sorted(list(supported_chains)))
    if refresh is not None and not isinstance(refresh, bool):
        return _err("VALIDATION_ERROR", "refresh must be a boolean when provided")

    api_keys = _load("api_keys.json")
    requests = _load("requests.json")

    def _pick_key():
        for k in api_keys:
            if k.get("status") != "active":
                continue
            allowed = k.get("allowed_chain_ids")
            if isinstance(allowed, list) and chain_id in allowed:
                return k
        return None

    key = _pick_key()
    if not key:
        return _err("UNAUTHORIZED", "No active API key is permitted to access this chain_id")

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    window_start_dt = now_dt - datetime.timedelta(seconds=60)
    day_start_dt = datetime.datetime.combine(now_dt.date(), datetime.time.min)

    key_id = key["id"]
    per_minute = int(key.get("rate_limit_per_minute", 0) or 0)
    daily_quota = int(key.get("daily_quota", 0) or 0)

    used_last_minute = 0
    used_today = 0
    for r in requests:
        if r.get("api_key_id") != key_id:
            continue
        ts = _parse_ts(r.get("created_at"))
        if not ts:
            continue
        if ts >= window_start_dt:
            used_last_minute += 1
        if ts >= day_start_dt:
            used_today += 1

    should_rate_limit = False
    rate_reason = None
    if key.get("status") != "active":
        should_rate_limit = True
        rate_reason = "API key is not active"
    elif per_minute and used_last_minute >= per_minute:
        should_rate_limit = True
        rate_reason = "Per-minute rate limit exceeded"
    elif daily_quota and used_today >= daily_quota:
        should_rate_limit = True
        rate_reason = "Daily quota exceeded"

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha256((prefix + now + str(time.time())).encode('utf-8')).hexdigest()[:24]}"

    req_id = _new_id("req")
    req_row = {
        "id": req_id,
        "api_key_id": key_id,
        "tool_name": "get-gas-prices",
        "chain_id": chain_id,
        "subject_address": None,
        "contract_address": None,
        "cache_hit": False,
        "upstream_provider": None,
        "upstream_http_status": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "response_ref": None,
        "latency_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    requests.append(req_row)
    _save("requests.json", requests)

    if should_rate_limit:
        req_row["status"] = "rate_limited"
        req_row["error_code"] = "RATE_LIMIT"
        req_row["error_message"] = rate_reason
        req_row["upstream_provider"] = "none"
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        _save("requests.json", requests)
        return _err("RATE_LIMIT", rate_reason, request_id=req_id)

    # Update api key usage
    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    # In-memory-like cache: emulate with module-local static via function attribute (persists in process)
    TTL_SECONDS = 30
    cache = getattr(get_gas_prices, "_cache", {})
    get_gas_prices._cache = cache
    cache_key = str(chain_id)
    cache_entry = cache.get(cache_key)
    cache_hit = False
    upstream_provider = "none"
    upstream_http_status = None

    def _is_fresh(entry):
        if not isinstance(entry, dict):
            return False
        ts = _parse_ts(entry.get("as_of"))
        if not ts:
            return False
        return (now_dt - ts).total_seconds() <= TTL_SECONDS

    if refresh is True:
        # attempt upstream; offline -> fail to refresh but still can serve cached if exists
        upstream_provider = "etherscan"
        upstream_http_status = 503
    else:
        if cache_entry and _is_fresh(cache_entry):
            cache_hit = True

    if refresh is True and not cache_hit:
        # Offline: cannot refresh; keep existing cache if any
        pass

    if not cache_entry:
        # no cached data; produce a deterministic placeholder derived from chain_id (not from store)
        # but rule: never fabricate rows not from store; gas prices have no table; acceptable to return computed estimates.
        base = {1: 25, 5: 2, 11155111: 2, 137: 60, 10: 0.2, 42161: 0.1, 56: 3}.get(chain_id, 10)
        cache_entry = {
            "as_of": now,
            "safe_gwei": float(base),
            "propose_gwei": float(base) * 1.2,
            "fast_gwei": float(base) * 1.5,
        }
        cache[cache_key] = cache_entry
        cache_hit = False if refresh else True  # first computation considered "cache fill"
        if upstream_provider == "none":
            upstream_provider = "none"
    else:
        if refresh is not True and cache_hit is False:
            # cache exists but stale; we "attempt" upstream only if refresh requested; otherwise serve stale with cache_hit=False
            pass

    body = {
        "chain_id": chain_id,
        "as_of": cache_entry.get("as_of"),
        "gas_prices_gwei": {
            "safe": cache_entry.get("safe_gwei"),
            "propose": cache_entry.get("propose_gwei"),
            "fast": cache_entry.get("fast_gwei"),
        },
        "cache": {"hit": bool(cache_hit)},
        "request_id": req_id,
    }

    req_row["status"] = "served"
    req_row["cache_hit"] = bool(cache_hit)
    req_row["upstream_provider"] = upstream_provider
    req_row["upstream_http_status"] = upstream_http_status
    req_row["response_ref"] = None
    req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
    req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("requests.json", requests)
    return body

