    should_rate_limit = False
    rate_reason = None
    if key.get("status") != "active":
        should_rate_limit = True
        rate_reason = "API key is not active"
    elif per_minute and used_last_minute >= per_minute:
        should_rate_limit = True
        rate_reason = "Per-minute rate limit exceeded"
    elif daily_quota and used_today >= daily_quota:
