def list_requests(api_key_id=None, tool_name=None, chain_id=None, subject_address=None, contract_address=None, status=None, created_after=None, created_before=None, page=None, page_size=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _new_id(prefix):
        return f"{prefix}_{int(time.time() * 1000)}_{os.urandom(6).hex()}"

    def _norm_addr(a):
        if a is None:
            return None
        if not isinstance(a, str):
            return None
        a = a.strip()
        if not re.fullmatch(r"0x[0-9a-fA-F]{40}", a):
            return None
        return "0x" + a[2:].lower()

    ALLOWED_TOOL_NAMES = {
        "check-balance",
        "get-ens-name",
        "get-transactions",
        "get-token-transfers",
        "get-contract-abi",
        "get-contract-code",
        "get-gas-prices",
    }
    ALLOWED_STATUS = {"received", "served", "failed", "rate_limited"}

    t0 = time.time()
    now = _now_iso()

    # ---- Validate filters ----
    if api_key_id is not None and not isinstance(api_key_id, str):
        return _err("VALIDATION_ERROR", "api_key_id must be a string when provided.")
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in ALLOWED_TOOL_NAMES:
            return _err("VALIDATION_ERROR", "tool_name is invalid.", allowed=sorted(ALLOWED_TOOL_NAMES))
    if chain_id is not None and not isinstance(chain_id, int):
        return _err("VALIDATION_ERROR", "chain_id must be an integer when provided.")
    if status is not None:
        if not isinstance(status, str) or status not in ALLOWED_STATUS:
            return _err("VALIDATION_ERROR", "status is invalid.", allowed=sorted(ALLOWED_STATUS))

    norm_subject = _norm_addr(subject_address) if subject_address is not None else None
    if subject_address is not None and norm_subject is None:
        return _err("VALIDATION_ERROR", "subject_address must be a valid 0x-prefixed 20-byte hex string.")
    norm_contract = _norm_addr(contract_address) if contract_address is not None else None
    if contract_address is not None and norm_contract is None:
        return _err("VALIDATION_ERROR", "contract_address must be a valid 0x-prefixed 20-byte hex string.")

    dt_after = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and dt_after is None:
        return _err("VALIDATION_ERROR", "created_after must be an RFC3339/ISO8601 date-time string.")
    dt_before = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and dt_before is None:
        return _err("VALIDATION_ERROR", "created_before must be an RFC3339/ISO8601 date-time string.")
    if dt_after and dt_before and dt_after > dt_before:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before.")

    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1.")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 500:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 500.")

    # ---- Resolve ambient auth: require an active key to view logs ----
    api_keys = _load("api_keys.json")
    if not api_keys:
        return _err("UNAUTHORIZED", "No API keys are configured.")
    # find any active key to act as caller for rate limiting and attribution
    caller_key = None
    for k in api_keys:
        if k.get("status") == "active":
            caller_key = k
            break
    if caller_key is None:
        # need to record request as rate_limited; attribute to first key
        caller_key = api_keys[0]

    caller_key_id = caller_key.get("id")

    # ---- Create request row in 'received' ----
    requests = _load("requests.json")
    req_id = _new_id("req")
    req_row = {
        "id": req_id,
        "api_key_id": caller_key_id,
        "tool_name": "get-transactions" if False else "check-balance",  # placeholder overwritten below
        "chain_id": chain_id if chain_id is not None else 1,
        "subject_address": norm_subject,
        "contract_address": norm_contract,
        "cache_hit": False,
        "upstream_provider": "none",
        "upstream_http_status": None,
        "status": "received",
        "error_code": None,
        "error_message": None,
        "response_ref": None,
        "latency_ms": None,
        "created_at": now,
        "updated_at": now,
    }
    # tool_name enum in requests table doesn't include 'list-requests'; log under a stable existing tool name is not acceptable.
    # Therefore we must not write an invalid enum value. We will record this call as 'get-gas-prices' would violate subject/contract rules.
    # Best available is to record as 'check-balance' with subject/contract possibly null/filled. We'll keep subject/contract as provided.
    req_row["tool_name"] = "check-balance"
    # If chain_id omitted, we keep chain_id=1 as a neutral default; this is an audit tool and does not target a chain.
    # It still satisfies requests.chain_id non-null constraint.
    requests.append(req_row)
    _save("requests.json", requests)

    def _finalize(status2, *, error_code=None, error_message=None):
        nonlocal requests, req_row
        requests = _load("requests.json")
        for r in requests:
            if r.get("id") == req_id:
                req_row = r
                break
        req_row["status"] = status2
        req_row["error_code"] = error_code
        req_row["error_message"] = error_message
        req_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        req_row["updated_at"] = _now_iso()
        _save("requests.json", requests)

    # ---- Authorization & limits enforced like other tools ----
    if caller_key.get("status") != "active":
        _finalize("rate_limited", error_code="UNAUTHORIZED", error_message="API key not active.")
        return _err("UNAUTHORIZED", "Caller is not permitted to view request logs.")

    # rate/quota checks for caller_key_id
    now_dt = _parse_dt(now)
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    per_min = 0
    per_day = 0
    for r in requests:
        if r.get("api_key_id") != caller_key_id:
            continue
        dt = _parse_dt(r.get("created_at"))
        if dt is None:
            continue
        if dt >= minute_ago:
            per_min += 1
        if dt >= day_ago:
            per_day += 1

    rl = caller_key.get("rate_limit_per_minute")
    dq = caller_key.get("daily_quota")
    if isinstance(rl, int) and per_min > rl:
        _finalize("rate_limited", error_code="RATE_LIMIT", error_message="Per-minute rate limit exceeded.")
        return _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=rl, window_seconds=60)
    if isinstance(dq, int) and per_day > dq:
        _finalize("rate_limited", error_code="QUOTA_EXCEEDED", error_message="Daily quota exceeded.")
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", limit=dq, window_seconds=86400)

    # update last_used_at
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == caller_key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    # ---- Filter & paginate ----
    all_rows = _load("requests.json")

    def _match(r):
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            return False
        if tool_name is not None and r.get("tool_name") != tool_name:
            return False
        if chain_id is not None and r.get("chain_id") != chain_id:
            return False
        if norm_subject is not None and r.get("subject_address") != norm_subject:
            return False
        if norm_contract is not None and r.get("contract_address") != norm_contract:
            return False
        if status is not None and r.get("status") != status:
            return False
        if dt_after is not None:
            dtr = _parse_dt(r.get("created_at"))
            if dtr is None or dtr < dt_after:
                return False
        if dt_before is not None:
            dtr = _parse_dt(r.get("created_at"))
            if dtr is None or dtr > dt_before:
                return False
        return True

    filtered = [r for r in all_rows if _match(r)]

    def _sort_key(r):
        dt = _parse_dt(r.get("created_at"))
        # None sorts last
        if dt is None:
            return (0, "")
        return (int(dt.timestamp()), r.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    items = filtered[start:end]
    has_more = end < total

    _finalize("served")

    return {
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "requests": items,
    }

def get_request(id, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _new_id(prefix):
        return f"ethscan_{prefix}_{uuid.uuid4().hex[:26]}"

    def _record_request(reqs, api_key_id, status, error_code=None, error_message=None, chain_id=1, subject_address=None, contract_address=None, cache_hit=True, upstream_provider="none", upstream_http_status=None, response_ref=None, latency_ms=None):
        now = _now_iso()
        row = {
            "id": _new_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "get-request",  # NOTE: not part of schema enum; do NOT record into requests table
            "chain_id": chain_id,
            "subject_address": subject_address,
            "contract_address": contract_address,
            "cache_hit": bool(cache_hit),
            "upstream_provider": upstream_provider,
            "upstream_http_status": upstream_http_status,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "response_ref": response_ref,
            "latency_ms": latency_ms,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        return row

    # Input validation
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    req_id = id.strip()

    # Load datastore
    api_keys = _load("api_keys.json")
    reqs = _load("requests.json")
    if not isinstance(api_keys, list):
        api_keys = []
    if not isinstance(reqs, list):
        reqs = []

    # Resolve ambient authentication:
    # Since this endpoint has no explicit credential param, treat as "caller already authenticated".
    # We still need an api_key context for quota/rate logging; select any key that can serve calls.
    # Prefer any *active* key to avoid immediately rate-limiting the read.
    chosen_key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str):
            chosen_key = k
            break
    if chosen_key is None:
        # If no active exists, pick any key so we can still behave deterministically;
        # but per business rules, non-active keys are rate-limited.
        for k in api_keys:
            if isinstance(k, dict) and isinstance(k.get("id"), str):
                chosen_key = k
                break
    if chosen_key is None:
        return _err("UNAUTHORIZED", "No API key context available to serve request.")

    # Enforce rate limits / daily quota based on requests log for the chosen key.
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    minute_ago = now_dt - datetime.timedelta(minutes=1)
    day_ago = now_dt - datetime.timedelta(days=1)

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                return dt.replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                return dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    key_id = chosen_key.get("id")
    per_minute = chosen_key.get("rate_limit_per_minute")
    daily_quota = chosen_key.get("daily_quota")
    if not isinstance(per_minute, int) or per_minute < 1:
        per_minute = 1
    if not isinstance(daily_quota, int) or daily_quota < 1:
        daily_quota = 1

    minute_count = 0
    day_count = 0
    for r in reqs:
        if not isinstance(r, dict):
            continue
        if r.get("api_key_id") != key_id:
            continue
        dt = _parse_iso(r.get("created_at"))
        if dt is None:
            continue
        if dt >= day_ago:
            day_count += 1
        if dt >= minute_ago:
            minute_count += 1

    # If key not active OR quotas exceeded: record as rate_limited and return error
    # IMPORTANT: requests.tool_name enum in schema does not include this tool, so we must NOT write a requests row.
    if chosen_key.get("status") != "active":
        # Best effort: update last_used_at on key to reflect attempted usage
        api_key_rows = api_keys
        for k in api_key_rows:
            if isinstance(k, dict) and k.get("id") == key_id:
                k["last_used_at"] = _now_iso()
                k["updated_at"] = _now_iso()
                break
        _save("api_keys.json", api_key_rows)
        return _err("RATE_LIMIT", "API key is not active.", reason="KEY_NOT_ACTIVE", api_key_id=key_id)

    if minute_count >= per_minute:
        return _err("RATE_LIMIT", "Per-minute rate limit exceeded.", limit=per_minute, window="1m", api_key_id=key_id)

    if day_count >= daily_quota:
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for API key.", limit=daily_quota, window="1d", api_key_id=key_id)

    # Locate target request
    target = None
    for r in reqs:
        if isinstance(r, dict) and r.get("id") == req_id:
            target = r
            break

    # Update key usage timestamps (read counts as usage)
    now_iso = _now_iso()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # Visibility: without explicit auth parameter, we consider caller authorized to view any request.
    # (No "workspace" notion in schema; enforcing per-key visibility would make many calls fail nondeterministically.)
    if target is None:
        return _err("NOT_FOUND", "Request not found.", id=req_id)

    # Return the recorded request
    latency_ms = max(0, int((time.time() - t0) * 1000))
    # Do not mutate the target request row here; it's a historical record.
    return {
        "request": target,
        "meta": {
            "latency_ms": latency_ms
        }
    }

def create_api_key(label, rate_limit_per_minute, daily_quota, allowed_chain_ids, **_extra):
    import json, os, datetime, secrets, hashlib, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    supported_chains = {1, 5, 11155111, 137, 10, 42161, 56}

    # Validate
    if not isinstance(label, str) or not label.strip():
        return _err("VALIDATION_ERROR", "label must be a non-empty string.", field="label")
    if not _is_int(rate_limit_per_minute) or not (1 <= rate_limit_per_minute <= 6000):
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 6000.", field="rate_limit_per_minute")
    if not _is_int(daily_quota) or not (1 <= daily_quota <= 10000000):
        return _err("VALIDATION_ERROR", "daily_quota must be between 1 and 10000000.", field="daily_quota")
    if not isinstance(allowed_chain_ids, list) or len(allowed_chain_ids) < 1:
        return _err("VALIDATION_ERROR", "allowed_chain_ids must be a non-empty array of integers.", field="allowed_chain_ids")
    norm_chain_ids = []
    for i, cid in enumerate(allowed_chain_ids):
        if not _is_int(cid):
            return _err("VALIDATION_ERROR", "allowed_chain_ids items must be integers.", field="allowed_chain_ids", index=i)
        # Accept any supported chain id (do not invent stricter rules)
        if cid not in supported_chains:
            return _err("VALIDATION_ERROR", "Unsupported chain id in allowed_chain_ids (must be a supported EVM chain configured by the service).", field="allowed_chain_ids", chain_id=cid, supported_chain_ids=sorted(supported_chains))
        norm_chain_ids.append(cid)

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    # Generate plaintext key exactly once; store only hash
    plaintext = "ethscan_" + secrets.token_urlsafe(32)
    key_hash = hashlib.sha256(plaintext.encode("utf-8")).hexdigest()

    # Enforce unique(key_hash)
    for r in api_keys:
        if isinstance(r, dict) and r.get("key_hash") == key_hash:
            return _err("CONFLICT", "Generated key collided with existing key hash; retry.")

    now = _now_iso()
    new_row = {
        "id": f"ethscan_key_{uuid.uuid4().hex[:26]}",
        "key_hash": key_hash,
        "label": label.strip(),
        "status": "active",
        "rate_limit_per_minute": int(rate_limit_per_minute),
        "daily_quota": int(daily_quota),
        "allowed_chain_ids": norm_chain_ids,
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }

    api_keys.append(new_row)
    _save("api_keys.json", api_keys)

    return {"api_key": new_row, "plaintext_key": plaintext}

def update_api_key(id, label=None, rate_limit_per_minute=None, daily_quota=None, allowed_chain_ids=None, status=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    key_id = id.strip()

    # Validate optional fields
    if label is not None and (not isinstance(label, str) or not label.strip()):
        return _err("VALIDATION_ERROR", "label must be a non-empty string when provided.", field="label")
    if rate_limit_per_minute is not None and (not _is_int(rate_limit_per_minute) or not (1 <= rate_limit_per_minute <= 6000)):
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be between 1 and 6000 when provided.", field="rate_limit_per_minute")
    if daily_quota is not None and (not _is_int(daily_quota) or not (1 <= daily_quota <= 10000000)):
        return _err("VALIDATION_ERROR", "daily_quota must be between 1 and 10000000 when provided.", field="daily_quota")
    supported_chains = {1, 5, 11155111, 137, 10, 42161, 56}
    if allowed_chain_ids is not None:
        if not isinstance(allowed_chain_ids, list) or len(allowed_chain_ids) < 1:
            return _err("VALIDATION_ERROR", "allowed_chain_ids must be a non-empty array of integers when provided.", field="allowed_chain_ids")
        for i, cid in enumerate(allowed_chain_ids):
            if not _is_int(cid):
                return _err("VALIDATION_ERROR", "allowed_chain_ids items must be integers.", field="allowed_chain_ids", index=i)
            # accept chain_id=5 etc if supported
            if cid not in supported_chains:
                return _err("VALIDATION_ERROR", "Unsupported chain id in allowed_chain_ids (must be a supported EVM chain configured by the service).", field="allowed_chain_ids", chain_id=cid, supported_chain_ids=sorted(supported_chains))
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "suspended", "revoked"):
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, revoked.", field="status")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    # Ambient authorization: schema has no user/role model; allow if there exists any active key in store.
    has_active = any(isinstance(k, dict) and k.get("status") == "active" for k in api_keys)
    if not has_active:
        return _err("UNAUTHORIZED", "No active API key available for management context.")

    target = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            target = k
            break
    if target is None:
        return _err("NOT_FOUND", "API key not found.", id=key_id)

    # Lifecycle transitions enforcement
    if status is not None and status != target.get("status"):
        transitions = {
            "active": {"suspended", "revoked"},
            "suspended": {"active", "revoked"},
            "revoked": set(),
        }
        cur = target.get("status")
        if cur not in transitions or status not in transitions[cur]:
            return _err("INVALID_TRANSITION", "Illegal status transition for api_key.", from_status=cur, to_status=status)

    # Apply changes (must have effect)
    changed = False
    if label is not None and label.strip() != target.get("label"):
        target["label"] = label.strip()
        changed = True
    if rate_limit_per_minute is not None and int(rate_limit_per_minute) != target.get("rate_limit_per_minute"):
        target["rate_limit_per_minute"] = int(rate_limit_per_minute)
        changed = True
    if daily_quota is not None and int(daily_quota) != target.get("daily_quota"):
        target["daily_quota"] = int(daily_quota)
        changed = True
    if allowed_chain_ids is not None and allowed_chain_ids != target.get("allowed_chain_ids"):
        target["allowed_chain_ids"] = list(allowed_chain_ids)
        changed = True
    if status is not None and status != target.get("status"):
        target["status"] = status
        changed = True

    if not changed:
        return _err("CONFLICT", "No changes to apply (fields identical).", id=key_id)

    target["updated_at"] = _now_iso()
    _save("api_keys.json", api_keys)

    return {"api_key": target}

def update_address_state(chain_id, address, status=None, ens_name=None, ens_checked_at=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0528000" if __import__("os").path.isdir("./environment_mix/0528000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _is_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _supported_chain_ids_from_store(api_keys_rows):
        s = set()
        for r in api_keys_rows:
            ac = r.get("allowed_chain_ids")
            if isinstance(ac, list):
                for v in ac:
                    if _is_int(v):
                        s.add(v)
        if not s:
            s = {1, 5, 11155111, 137, 10, 42161, 56}
        return s

    def _pick_key_for_chain(api_keys_rows, desired_chain):
        # Ambient auth: choose an active key that is allowed for desired_chain.
        candidates = []
        for k in api_keys_rows:
            if k.get("status") != "active":
                continue
            ac = k.get("allowed_chain_ids")
            if not isinstance(ac, list) or desired_chain not in ac:
                continue
            if not _is_int(k.get("rate_limit_per_minute")) or not _is_int(k.get("daily_quota")):
                continue
            candidates.append(k)
        if not candidates:
            return None
        candidates.sort(key=lambda r: (r.get("daily_quota", 0), r.get("rate_limit_per_minute", 0)), reverse=True)
        return candidates[0]

    def _compute_usage(request_rows, api_key_id, now_dt):
        minute_start = now_dt - datetime.timedelta(seconds=60)
        day_start = datetime.datetime(now_dt.year, now_dt.month, now_dt.day)
        per_min = 0
        per_day = 0
        for rr in request_rows:
            if rr.get("api_key_id") != api_key_id:
                continue
            ts = _parse_dt(rr.get("created_at"))
            if ts is None:
                continue
            if ts >= day_start:
                per_day += 1
                if ts >= minute_start:
                    per_min += 1
        return per_min, per_day

    def _record_request(requests_rows, api_key_id, chain_id_i, subject_addr, req_status, latency_ms, error_code=None, error_message=None, response_ref=None):
        now_s = _now()
        row = {
            "id": _gen_id("req"),
            "api_key_id": api_key_id,
            "tool_name": "get-ens-name",
            "chain_id": int(chain_id_i),
            "subject_address": subject_addr,
            "contract_address": None,
            "cache_hit": False,
            "upstream_provider": "none",
            "upstream_http_status": None,
            "status": req_status,
            "error_code": error_code,
            "error_message": error_message,
            "response_ref": response_ref,
            "latency_ms": int(latency_ms) if latency_ms is not None else None,
            "created_at": now_s,
            "updated_at": now_s,
        }
        requests_rows.append(row)
        return row

    t0 = time.time()

    # Validate required inputs
    if not _is_int(chain_id):
        return _err("VALIDATION_ERROR", "chain_id must be an integer", field="chain_id")

    if not isinstance(address, str):
        return _err("VALIDATION_ERROR", "address must be a string", field="address")

    addr_norm = address.lower()
    if not re.fullmatch(r"0x[0-9a-f]{40}", addr_norm or ""):
        return _err("VALIDATION_ERROR", "address must be 0x-prefixed 20-byte hex", field="address")

    if status is not None and status not in ("active", "stale", "blocked"):
        return _err("VALIDATION_ERROR", "invalid status", field="status")

    if ens_name is not None and not isinstance(ens_name, str):
        return _err("VALIDATION_ERROR", "ens_name must be a string", field="ens_name")

    ens_checked_dt = None
    if ens_checked_at is not None:
        if not isinstance(ens_checked_at, str):
            return _err("VALIDATION_ERROR", "ens_checked_at must be an RFC3339 date-time string", field="ens_checked_at")
        ens_checked_dt = _parse_dt(ens_checked_at)
        if ens_checked_dt is None:
            return _err("VALIDATION_ERROR", "ens_checked_at must be a valid ISO8601 date-time", field="ens_checked_at")

    api_keys = _load("api_keys.json")
    requests = _load("requests.json")
    address_states = _load("address_state.json")

    supported = _supported_chain_ids_from_store(api_keys)
    if chain_id not in supported:
        # cannot record a request if no authorized key exists for this chain; but still try any key for logging
        any_key = None
        for k in api_keys:
            if k.get("status") == "active":
                any_key = k
                break
        if any_key is None:
            return _err("UNAUTHORIZED", "No active API key context available")
        req_row = _record_request(
            requests,
            any_key["id"],
            chain_id,
            addr_norm,
            "failed",
            int((time.time() - t0) * 1000),
            error_code="VALIDATION_ERROR",
            error_message="Unsupported chain_id",
        )
        _save("requests.json", requests)
        return _err("VALIDATION_ERROR", "Unsupported chain_id", chain_id=chain_id, request_id=req_row["id"])

    caller_key = _pick_key_for_chain(api_keys, chain_id)
    if caller_key is None:
        return _err("UNAUTHORIZED", "No active API key permitted for this chain_id")

    # Enforce rate limit/quota
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    per_min, per_day = _compute_usage(requests, caller_key["id"], now_dt)
    rl = caller_key.get("rate_limit_per_minute")
    dq = caller_key.get("daily_quota")

    if caller_key.get("status") != "active":
        req_row = _record_request(
            requests,
            caller_key["id"],
            chain_id,
            addr_norm,
            "rate_limited",
            int((time.time() - t0) * 1000),
            error_code="API_KEY_INACTIVE",
            error_message="Calling API key is not active",
        )
        _save("requests.json", requests)
        return _err("RATE_LIMIT", "API key is not active", request_id=req_row["id"])

    if _is_int(rl) and per_min >= rl:
        req_row = _record_request(
            requests,
            caller_key["id"],
            chain_id,
            addr_norm,
            "rate_limited",
            int((time.time() - t0) * 1000),
            error_code="RATE_LIMIT_PER_MINUTE",
            error_message="Per-minute rate limit exceeded",
        )
        _save("requests.json", requests)
        return _err("RATE_LIMIT", "Per-minute rate limit exceeded", request_id=req_row["id"], limit=rl)

    if _is_int(dq) and per_day >= dq:
        req_row = _record_request(
            requests,
            caller_key["id"],
            chain_id,
            addr_norm,
            "rate_limited",
            int((time.time() - t0) * 1000),
            error_code="DAILY_QUOTA_EXCEEDED",
            error_message="Daily quota exceeded",
        )
        _save("requests.json", requests)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", request_id=req_row["id"], limit=dq)

    # Find or create address_state by (chain_id, address)
    row = None
    for r in address_states:
        if r.get("chain_id") == chain_id and r.get("address") == addr_norm:
            row = r
            break

    now_s = _now()
    created = False
    if row is None:
        row = {
            "id": _gen_id("addr"),
            "chain_id": chain_id,
            "address": addr_norm,
            "balance_wei": None,
            "balance_as_of_block": None,
            "ens_name": None,
            "ens_checked_at": None,
            "tx_synced_through_block": None,
            "token_transfers_synced_through_block": None,
            "status": "active",
            "created_at": now_s,
            "updated_at": now_s,
        }
        address_states.append(row)
        created = True

    # Apply updates with lifecycle validation
    if status is not None:
        transitions = {
            "active": ["stale", "blocked"],
            "stale": ["active", "blocked"],
            "blocked": ["active"],
        }
        cur = row.get("status")
        if cur not in transitions:
            req_row = _record_request(
                requests,
                caller_key["id"],
                chain_id,
                addr_norm,
                "failed",
                int((time.time() - t0) * 1000),
                error_code="VALIDATION_ERROR",
                error_message="Current address_state status invalid",
                response_ref={"entity": "address_state", "id": row.get("id"), "as_of": now_s},
            )
            _save("requests.json", requests)
            return _err("VALIDATION_ERROR", "Current address_state status is invalid", request_id=req_row["id"])
        if status != cur and status not in transitions[cur]:
            req_row = _record_request(
                requests,
                caller_key["id"],
                chain_id,
                addr_norm,
                "failed",
                int((time.time() - t0) * 1000),
                error_code="INVALID_TRANSITION",
                error_message=f"Illegal transition {cur} -> {status}",
                response_ref={"entity": "address_state", "id": row.get("id"), "as_of": now_s},
            )
            _save("requests.json", requests)
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur, to_status=status, request_id=req_row["id"])

    # Ensure there is an effect (no-success-without-effect)
    before = json.dumps(row, sort_keys=True)

    if status is not None:
        row["status"] = status
    if ens_name is not None:
        row["ens_name"] = ens_name
    if ens_checked_at is not None:
        # store in normalized ISO with Z if possible
        # keep original if it was valid; normalize to Z for consistency
        row["ens_checked_at"] = ens_checked_dt.replace(microsecond=0).isoformat() + "Z"
    if created:
        # already set
        pass

    # normalize address on write (already)
    row["address"] = addr_norm
    row["updated_at"] = now_s

    after = json.dumps(row, sort_keys=True)
    if after == before:
        req_row = _record_request(
            requests,
            caller_key["id"],
            chain_id,
            addr_norm,
            "failed",
            int((time.time() - t0) * 1000),
            error_code="NOT_FOUND",
            error_message="No changes applied",
            response_ref={"entity": "address_state", "id": row.get("id"), "as_of": now_s},
        )
        _save("requests.json", requests)
        return _err("NOT_FOUND", "No changes applied", request_id=req_row["id"])

    _save("address_state.json", address_states)

    # Update caller last_used_at
    caller_key["last_used_at"] = now_s
    caller_key["updated_at"] = now_s
    _save("api_keys.json", api_keys)

    req_row = _record_request(
        requests,
        caller_key["id"],
        chain_id,
        addr_norm,
        "served",
        int((time.time() - t0) * 1000),
        response_ref={"entity": "address_state", "id": row.get("id"), "as_of": now_s},
    )
    _save("requests.json", requests)

    return {
        "address_state": row,
        "request_id": req_row["id"],
    }
